-- Add Sydney sample stays so Hotels search and Myra share the same inventory.
-- Rates are demo values stored in INR; Myra converts them to the saved display currency.
on conflict (id) do update set city=excluded.city,name=excluded.name,price_per_night_inr=excluded.price_per_night_inr,area=excluded.area,tags=excluded.tags,lat=excluded.lat,lng=excluded.lng,address=excluded.address,photos=excluded.photos;
create index if not exists catalogue_hotels_city_name on public.catalogue_hotels(lower(city),name);
